const crypto = require('crypto');
const root = $input.first().json;
const body = root.body ?? root;
const data = Array.isArray(body.data) ? body.data[0] : body.data;

if (!data || !data.key) {
  return [{ json: { skip: true, reason: 'no_data' } }];
}

if (data.key.fromMe === true) {
  return [{ json: { skip: true, reason: 'from_me' } }];
}

const remoteJid = String(data.key.remoteJid || '');
if (!remoteJid || remoteJid.endsWith('@g.us') || remoteJid === 'status@broadcast') {
  return [{ json: { skip: true, reason: 'ignored_jid' } }];
}

const digits = remoteJid.replace(/@.*$/, '').replace(/\D/g, '');
if (digits.length < 10) {
  return [{ json: { skip: true, reason: 'invalid_phone' } }];
}

const normalizedPhone = digits.startsWith('55') ? `+${digits}` : `+55${digits}`;
const message = data.message || {};
const contentText =
  message.conversation ||
  message.extendedTextMessage?.text ||
  message.imageMessage?.caption ||
  message.documentMessage?.caption ||
  message.videoMessage?.caption ||
  null;

let messageType = 'text';
if (message.imageMessage) messageType = 'image';
else if (message.documentMessage) messageType = 'document';
else if (message.audioMessage) messageType = 'audio';
else if (message.videoMessage) messageType = 'video';
else if (message.stickerMessage) messageType = 'sticker';
else if (message.locationMessage) messageType = 'location';

const inboundBody = {
  normalizedPhone,
  channelMessageId: data.key.id || undefined,
  payload: {
    messageType,
    contentText,
    mediaUrl: null,
    caption: message.imageMessage?.caption || message.documentMessage?.caption || null,
    mediaFileName: message.documentMessage?.fileName || null,
    linkPreview: null,
    pushName: data.pushName || null,
  },
};

const requestBodyString = JSON.stringify(inboundBody);
const secret = $env.BACKOFFICE_STUDIO_BOT_WEBHOOK_SECRET || '';
const hash = crypto.createHmac('sha256', secret).update(requestBodyString).digest('hex');
const base = ($env.LEAD_FLOW_API_BASE_URL || '').replace(/\/$/, '');

return [{
  json: {
    skip: false,
    inboundBody,
    requestBodyString,
    hmacSignature: `sha256=${hash}`,
    inboundUrl: `${base}/api/webhooks/backoffice/studio-bot/inbound`,
    idempotencyKey: data.key.id || undefined,
  },
}];
